void wpa_supplicant_event(void *ctx, enum wpa_event_type event,
			  union wpa_event_data *data)
{
	struct wpa_supplicant *wpa_s = ctx;
	int resched;
#ifndef CONFIG_NO_STDOUT_DEBUG
	int level = MSG_DEBUG;
#endif /* CONFIG_NO_STDOUT_DEBUG */

	if (event == EVENT_SCAN_STARTED || event == EVENT_SCAN_RESULTS ||
	    event == EVENT_ASSOC || event == EVENT_ASSOC_REJECT ||
	    event == EVENT_DEAUTH || event == EVENT_DISASSOC) {
		AIC_LOG_PRINTF("AIC_WPA_EVT: event=%d ifname=%s state=%s data=%p ext=%d aborted=%d nl=%d\r\n",
			       event, wpa_s ? wpa_s->ifname : "null",
			       wpa_s ? wpa_supplicant_state_txt(wpa_s->wpa_state) : "null",
			       data,
			       (event == EVENT_SCAN_RESULTS && data) ?
			       data->scan_info.external_scan : -1,
			       (event == EVENT_SCAN_RESULTS && data) ?
			       data->scan_info.aborted : -1,
			       (event == EVENT_SCAN_RESULTS && data) ?
			       data->scan_info.nl_scan_event : -1);
	}

	if (wpa_s->wpa_state == WPA_INTERFACE_DISABLED &&
	    event != EVENT_INTERFACE_ENABLED &&
	    event != EVENT_INTERFACE_STATUS &&
	    event != EVENT_SCAN_RESULTS &&
	    event != EVENT_SCHED_SCAN_STOPPED) {
		wpa_dbg(wpa_s, MSG_DEBUG,
			"Ignore event %s (%d) while interface is disabled",
			event_to_string(event), event);
		return;
	}

#ifndef CONFIG_NO_STDOUT_DEBUG
	if (event == EVENT_RX_MGMT && data->rx_mgmt.frame_len >= 24) {
		const struct ieee80211_hdr *hdr;
		u16 fc;
		hdr = (const struct ieee80211_hdr *) data->rx_mgmt.frame;
		fc = le_to_host16(hdr->frame_control);
