      pthread_mutex_unlock(&g_wifi_lock);
      ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_STATE_CHANGED);
      return -EBUSY;
    }

  first_start = !g_wifi.enabled;
  g_wifi.enabled = true;
  g_wifi.scan_in_progress = true;
  g_wifi.scan_needs_start = first_start;
