static int wpas_select_network_from_last_scan(struct wpa_supplicant *wpa_s,
					      int new_scan, int own_request)
{
	struct wpa_bss *selected;
	struct wpa_ssid *ssid = NULL;
	int time_to_reenable = wpas_reenabled_network_time(wpa_s);

	if (time_to_reenable > 0) {
		wpa_dbg(wpa_s, MSG_DEBUG,
			"Postpone network selection by %d seconds since all networks are disabled",
			time_to_reenable);
		eloop_cancel_timeout(wpas_network_reenabled, wpa_s, NULL);
		eloop_register_timeout(time_to_reenable, 0,
				       wpas_network_reenabled, wpa_s, NULL);
		return 0;
	}

	if (wpa_s->p2p_mgmt)
		return 0; /* no normal connection on p2p_mgmt interface */

	wpa_s->owe_transition_search = 0;
	selected = wpa_supplicant_pick_network(wpa_s, &ssid);
	AIC_LOG_PRINTF("AIC_WPA_PICK: selected=%p ssid=%p state=%s last_used=%u new=%d own=%d\r\n",
		       selected, ssid, wpa_supplicant_state_txt(wpa_s->wpa_state),
		       wpa_s->last_scan_res_used, new_scan, own_request);
	wpa_printf(MSG_INFO,
		   "AIC_WPA_PICK: selected=%p ssid=%p state=%s new_scan=%d own=%d",
		   selected, ssid, wpa_supplicant_state_txt(wpa_s->wpa_state),
		   new_scan, own_request);

#ifdef CONFIG_MESH
	if (wpa_s->ifmsh) {
		wpa_msg(wpa_s, MSG_INFO,
			"Avoiding join because we already joined a mesh group");
