		AIC_LOG_PRINTF("AIC_WPA_PICK: use bssid=" MACSTR
			       " ssid='%s' network_id=%d skip=%d\r\n",
			       MAC2STR(selected->bssid),
			       wpa_ssid_txt(selected->ssid, selected->ssid_len),
			       ssid ? ssid->id : -1, skip);
		wpa_printf(MSG_INFO,
			   "AIC_WPA_PICK: use bssid=" MACSTR
			   " ssid='%s' network_id=%d skip=%d",
