void rtos_task_suspend(int duration)
{
    if (-1 == duration) {
        /* Suspend forever - sleep in a loop */
        while (1) {
            nxsig_usleep(100000000);  /* 100s chunks */
        }
    } else if (duration > 0) {
        rtos_msleep((uint32_t)duration);
    }
}

